content.content:
1	/* claudinite.com — design system.
2	   Palette: warm paper + ink monochrome, one malachite accent, semantic
3	   red/amber/green reserved for check states. Type: system grotesk + mono.
4	   Motion: reveal-on-scroll + mechanism loops, all gated by
5	   prefers-reduced-motion. No webfonts, no frameworks; the only external asset
6	   is the cookieless analytics beacon (see assets/analytics.js, privacy.html). */
7	
8	:root {
9	  --paper: #faf8f4;
10	  --paper-2: #f3f0e8;
11	  --ink: #16180f;
12	  --ink-soft: #5c6055;
13	  --line: #e4dfd2;
14	  --accent: #0e7c52;
15	  --accent-deep: #0a5c3e;
16	  --accent-wash: #e3efe6;
17	  --red: #c2402f;
18	  --red-wash: #f7e4e0;
19	  --amber: #b57816;
20	  --amber-wash: #f6ecd8;
21	  --term-bg: #141712;
22	  --radius: 14px;
23	  --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", "Inter", system-ui, Roboto, "Helvetica Neue", Arial, sans-serif;
24	  --mono: ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;
25	}
26	
27	* { box-sizing: border-box; margin: 0; padding: 0; }
28	html { scroll-behavior: smooth; }
29	body {
30	  font-family: var(--sans);
31	  background: var(--paper);
32	  color: var(--ink);
33	  line-height: 1.6;
34	  font-size: 17px;
35	  -webkit-font-smoothing: antialiased;
36	  text-rendering: optimizeLegibility;
37	}
38	
39	.wrap { max-width: 1140px; margin: 0 auto; padding: 0 24px; }
40	.wrap-narrow { max-width: 780px; }
41	
42	h1, h2, h3 { line-height: 1.06; letter-spacing: -0.025em; font-weight: 700; text-wrap: balance; }
43	h1 { font-size: clamp(2.7rem, 6.4vw, 4.9rem); }
44	h2 { font-size: clamp(2rem, 4.4vw, 3.1rem); margin-bottom: 0.55em; }
45	h3 { font-size: 1.15rem; letter-spacing: -0.01em; }
46	p { max-width: 62ch; }
47	code, .mono {
48	  font-family: var(--mono);
49	  font-size: 0.88em;
50	  background: var(--paper-2);
51	  border: 1px solid var(--line);
52	  border-radius: 5px;
53	  padding: 0.08em 0.35em;
54	  white-space: nowrap;
55	}
56	.mono b { color: var(--accent-deep); }
57	::selection { background: var(--accent); color: #fff; }
58	
59	.skip {
60	  position: absolute; left: -9999px; top: 0;
61	  background: var(--ink); color: var(--paper); padding: 10px 16px; z-index: 99;
62	}
63	.skip:focus { left: 12px; top: 12px; }
64	
65	.eyebrow {
66	  font-family: var(--mono);
67	  font-size: 0.72rem;
68	  letter-spacing: 0.16em;
69	  text-transform: uppercase;
70	  color: var(--accent-deep);
71	  margin-bottom: 1.1em;
72	}
73	.eyebrow::before { content: "◆ "; font-size: 0.85em; }
74	
75	/* ------------------------------- nav ------------------------------- */
76	.nav {
77	  position: sticky; top: 0; z-index: 50;
78	  background: color-mix(in srgb, var(--paper) 88%, transparent);
79	  backdrop-filter: blur(10px);
80	  border-bottom: 1px solid var(--line);
81	}
82	.nav-inner {
83	  max-width: 1140px; margin: 0 auto; padding: 14px 24px;
84	  display: flex; align-items: center; justify-content: space-between; gap: 16px;
85	}
86	.brand {
87	  display: inline-flex; align-items: center; gap: 9px;
88	  font-family: var(--mono); font-weight: 700; font-size: 1.05rem;
89	  color: var(--ink); text-decoration: none; letter-spacing: -0.02em;
90	}
91	.brand-glyph { width: 22px; height: 22px; color: var(--accent); }
92	.nav nav { display: flex; align-items: center; gap: 22px; }
93	.nav nav a {
94	  color: var(--ink-soft); text-decoration: none; font-size: 0.92rem; font-weight: 550;
95	}
96	.nav nav a:hover { color: var(--ink); }
97	.nav-cta {
98	  color: #fff !important; background: var(--ink);
99	  padding: 7px 15px; border-radius: 999px;
100	}
101	.nav-cta:hover { background: var(--accent-deep); }
102	
103	/* ------------------------------ buttons ---------------------------- */
104	.btn {
105	  display: inline-block; text-decoration: none; font-weight: 620; font-size: 0.98rem;
106	  padding: 13px 24px; border-radius: 999px; border: 1.5px solid var(--ink);
107	  transition: transform 0.15s ease, background 0.15s ease, color 0.15s ease, box-shadow 0.15s ease;
108	}
109	.btn:active { transform: translateY(1px); }
110	.btn-primary { background: var(--ink); color: var(--paper); }
111	.btn-primary:hover { background: var(--accent-deep); border-color: var(--accent-deep); box-shadow: 0 6px 24px -8px var(--accent-deep); }
112	.btn-ghost { color: var(--ink); background: transparent; }
113	.btn-ghost:hover { background: var(--paper-2); }
114	.cta-row { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 1.8em; }
115	
116	/* ------------------------------- hero ------------------------------ */
117	.hero { padding: clamp(56px, 8vw, 104px) 0 clamp(40px, 6vw, 72px); overflow: hidden; }
118	.hero-copy { max-width: 46rem; }
119	.lede { font-size: clamp(1.05rem, 1.7vw, 1.24rem); color: var(--ink-soft); margin-top: 1.2em; }
120	.lede strong { color: var(--ink); }
121	.hero-fine { font-size: 0.85rem; color: var(--ink-soft); margin-top: 1.2em; font-family: var(--mono); }
122	h1 { margin-top: 0.2em; }
123	
124	.viz-caption {
125	  font-family: var(--mono); font-size: 0.72rem; color: var(--ink-soft);
126	  text-align: center; margin-top: 4px; letter-spacing: 0.06em;
127	}
128	
129	.crystal { fill: var(--accent-wash); stroke: var(--accent-deep); stroke-width: 2; stroke-linejoin: round; }
130	.crystal-facets, .crystal-center-facets { fill: none; stroke: var(--accent-deep); stroke-width: 1; opacity: 0.6; }
131	.viz-label { font-family: var(--mono); font-size: 13px; fill: var(--ink-soft); letter-spacing: 0.08em; }
132	
133	/* ---------------------- the compounding chart ----------------------
134	   The page's central argument. Curves and end-state meter widths are authored
135	   in the markup; assets/main.js only animates the reveal. */
136	.compound { margin: clamp(32px, 5vw, 56px) auto 0; max-width: 960px; }
137	.compound svg { width: 100%; height: auto; display: block; overflow: visible; }
138	
139	.cx-axis line { stroke: var(--line); stroke-width: 1.5; }
140	.cx-axis-label,
141	.cx-meter-head,
142	.cx-meter-label,
143	.cx-caption,
144	.cx-pin text {
145	  font-family: var(--mono); fill: var(--ink-soft); letter-spacing: 0.06em;
146	}
147	.cx-axis-label { font-size: 13px; text-transform: uppercase; }
148	.cx-meter-head { font-size: 13px; text-transform: uppercase; }
149	.cx-meter-label { font-size: 14px; }
150	.cx-caption { font-size: 13px; }
151	.cx-end { text-anchor: end; }
152	
153	/* The distance between the two paths — what the lede calls the compounding. */
154	.cx-gap { fill: var(--accent-wash); stroke: none; }
155	.cx-line { fill: none; stroke-width: 3.5; stroke-linecap: round; stroke-linejoin: round; }
156	.cx-prose { stroke: var(--ink-soft); opacity: 0.45; stroke-dasharray: 7 6; }
157	.cx-claud { stroke: var(--accent); }
158	
159	.cx-key { font-family: var(--mono); font-size: 15px; font-weight: 700; letter-spacing: 0.04em; }
160	.cx-key-prose { fill: var(--ink-soft); }
161	.cx-key-claud { fill: var(--accent-deep); }
162	
163	/* The plateau marker only makes sense once the prose meter has actually
164	   filled, so it is held back until the sweep reaches that session. */
165	.cx-pin circle { fill: var(--red); }
166	.cx-pin text { font-size: 13px; fill: var(--red); }
167	.cx-pin, .cx-key { opacity: 1; transition: opacity 0.5s ease; }
168	.cx-running .cx-pin, .cx-running .cx-key { opacity: 0; }
169	.cx-running.cx-pinned .cx-pin { opacity: 1; }
170	.cx-running.cx-late .cx-key { opacity: 1; }
171	
172	.cx-meter-frame { fill: var(--paper-2); stroke: var(--line); stroke-width: 1.5; }
173	.cx-fill-prose { fill: var(--red); opacity: 0.75; }
174	.cx-fill-claud { fill: var(--accent); }
175	
176	/* Each promotion hands budget back; the flash is that moment. */
177	.cx-freed { animation: cx-freed 0.6s ease-out; }
178	@keyframes cx-freed { 0% { fill: #7fd4ac; } 100% { fill: var(--accent); } }
179	
180	.compound-caption {
181	  display: flex; align-items: center; justify-content: center;
182	  gap: 14px; flex-wrap: wrap; margin-top: 10px;
183	}
184	
185	.cx-replay {
186	  font-family: var(--mono); font-size: 0.78rem; letter-spacing: 0.06em;
187	  color: var(--ink-soft); background: none; border: 1px solid var(--line);
188	  border-radius: 999px; padding: 5px 14px; cursor: pointer;
189	}
190	.cx-replay:hover { color: var(--ink); border-color: var(--ink-soft); }
191	
192	/* ------------------------------- why ------------------------------- */
193	.why { padding: clamp(56px, 9vw, 120px) 0; border-top: 1px solid var(--line); background: var(--paper-2); }
194	.why-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; margin-top: 2.2em; }
195	.why-card {
196	  background: var(--paper); border: 1px solid var(--line); border-radius: var(--radius);
197	  padding: 26px 24px;
198	}
199	.why-card h3 { margin-bottom: 0.6em; display: flex; align-items: baseline; gap: 10px; }
200	.why-num { font-family: var(--mono); font-size: 0.72rem; color: var(--accent-deep); letter-spacing: 0.1em; }
201	.why-card p { font-size: 0.95rem; color: var(--ink-soft); }
202	.why-kicker {
203	  margin-top: 2.4em; font-size: clamp(1.1rem, 2vw, 1.35rem); letter-spacing: -0.01em;
204	  max-width: 46ch; color: var(--ink-soft);
205	}
206	.why-kicker strong { color: var(--accent-deep); }
207	
208	/* The one quotation on the page: the platform vendor stating the premise. */
209	.quote {
210	  margin: 2em 0 2.6em; padding-left: clamp(14px, 2vw, 22px);
211	  border-left: 3px solid var(--accent);
212	}
213	.quote p {
214	  font-size: clamp(1.25rem, 2.6vw, 1.75rem); line-height: 1.25;
215	  letter-spacing: -0.02em; font-weight: 600; max-width: 24ch;
216	}
217	.quote cite { display: block; margin-top: 0.7em; font-style: normal; font-size: 0.85rem; color: var(--ink-soft); }
218	.quote cite a { color: inherit; }
219	
220	/* --------------------------- mechanism grid ------------------------ */
221	.mech { padding: clamp(64px, 10vw, 130px) 0; border-top: 1px solid var(--line); }
222	.mech-grid {
223	  display: grid; grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr);
224	  gap: clamp(32px, 6vw, 80px); align-items: center;
225	}
226	.mech-grid-flip > .mech-copy { order: 2; }
227	.mech-points { margin: 1.4em 0 0 1.1em; display: grid; gap: 0.55em; color: var(--ink-soft); }
228	.mech-points li::marker { color: var(--accent); }
229	.mech-points strong { color: var(--ink); }
230	.mech-fine { font-size: 0.88rem; color: var(--ink-soft); margin-top: 1em; }
231	
232	/* pack anatomy */
233	.pack-stack { display: grid; gap: 14px; perspective: 900px; }
234	.pack-layer {
235	  background: var(--paper); border: 1.5px solid var(--ink); border-radius: var(--radius);
236	  padding: 18px 20px; box-shadow: 0 2px 0 var(--ink);
237	}
238	.pack-layer p { font-size: 0.92rem; color: var(--ink-soft); max-width: none; }
239	.pack-layer-head { display: flex; align-items: center; gap: 10px; margin-bottom: 8px; flex-wrap: wrap; }
240	.file { font-family: var(--mono); font-weight: 700; font-size: 0.98rem; }
241	.pill {
242	  font-family: var(--mono); font-size: 0.66rem; letter-spacing: 0.08em; text-transform: uppercase;
243	  background: var(--accent-wash); color: var(--accent-deep);
244	  border-radius: 999px; padding: 3px 10px;
245	}
246	.pill-red { background: var(--red-wash); color: var(--red); }
247	.pill-amber { background: var(--amber-wash); color: var(--amber); }
248	
249	/* reveal-on-scroll */
250	.reveal { opacity: 0; transform: translateY(22px); transition: opacity 0.6s ease, transform 0.6s ease; }
251	.reveal[data-delay="1"] { transition-delay: 0.12s; }
252	.reveal[data-delay="2"] { transition-delay: 0.24s; }
253	.reveal[data-delay="3"] { transition-delay: 0.36s; }
254	.reveal[data-delay="4"] { transition-delay: 0.48s; }
255	.reveal.in { opacity: 1; transform: none; }
256	
257	/* --------------------------- terminals ----------------------------- */
258	.mech-dark { background: var(--term-bg); color: #eef1ea; border-top: none; }
259	.mech-dark .eyebrow { color: #7fd4ac; }
260	.mech-dark h2 { color: #f4f6ef; }
261	.mech-dark p, .mech-dark .mech-points { color: #a9b3a2; }
262	.mech-dark .mech-points strong, .mech-dark em { color: #e8ecdf; }
263	.mech-dark .btn-ghost { color: #eef1ea; border-color: #eef1ea; }
264	.mech-dark .btn-ghost:hover { background: rgba(255, 255, 255, 0.08); }
265	.btn-replay { margin-top: 1.6em; font-family: var(--mono); font-size: 0.85rem; padding: 9px 18px; cursor: pointer; }
266	
267	.terminal {
268	  background: #0e110c; border: 1px solid #2a2f26; border-radius: var(--radius);
269	  overflow: hidden; box-shadow: 0 24px 60px -30px rgba(0, 0, 0, 0.55);
270	  font-family: var(--mono); font-size: 0.84rem;
271	}
272	.term-bar {
273	  display: flex; align-items: center; gap: 7px; padding: 11px 14px;
274	  background: #171b14; border-bottom: 1px solid #2a2f26;
275	}
276	.term-bar span { width: 10px; height: 10px; border-radius: 50%; background: #3a4034; }
277	.term-bar em { font-style: normal; color: #8b947f; font-size: 0.72rem; margin-left: 8px; }
278	.term-body { padding: 18px 18px 22px; display: grid; gap: 7px; }
279	.t-line { color: #d9e2d3; max-width: none; line-height: 1.5; }
280	.t-dim { color: #79826d; }
281	.t-hook { color: #9ab8ff; }
282	.t-bad { color: #ff8d7a; }
283	.t-good { color: #74d99f; }
284	.t-tag {
285	  font-size: 0.64rem; text-transform: uppercase; letter-spacing: 0.1em;
286	  background: rgba(255, 141, 122, 0.15); color: #ff8d7a;
287	  border-radius: 4px; padding: 1px 6px; margin: 0 4px;
288	}
289	.terminal code, .terminal .mono {
290	  background: transparent; border: none; padding: 0;
291	  color: #7fd4ac; font-size: inherit;
292	}
293	#term-body .t-line { opacity: 0; transform: translateY(4px); transition: opacity 0.35s ease, transform 0.35s ease; }
294	#term-body .t-line.on { opacity: 1; transform: none; }
295	
296	.terminal-light { box-shadow: 0 24px 60px -34px rgba(22, 24, 15, 0.5); }
297	.caret {
298	  display: inline-block; width: 8px; height: 1.05em; background: #74d99f;
299	  vertical-align: text-bottom; margin-left: 2px; animation: blink 1s steps(1) infinite;
300	}
301	@keyframes blink { 50% { opacity: 0; } }
302	.adopt-result { display: grid; gap: 7px; opacity: 0; transition: opacity 0.5s ease; }
303	.adopt-result.on { opacity: 1; }
304	
305	/* --------------------------- fleet board --------------------------- */
306	.fleet-board {
307	  border: 1.5px solid var(--ink); border-radius: var(--radius); background: var(--paper);
308	  padding: 20px; box-shadow: 0 2px 0 var(--ink);
309	}
310	.canon-bar {
311	  display: flex; align-items: center; gap: 12px; padding: 10px 14px;
312	  background: var(--ink); color: var(--paper); border-radius: 10px;
313	  font-size: 0.9rem; position: relative; overflow: hidden;
314	}
315	.canon-bar .mono { background: none; border: none; color: var(--paper); }
316	.canon-bar .mono b { color: #7fd4ac; }
317	.clock { width: 26px; height: 26px; color: #7fd4ac; }
318	.clock-hand { transform-origin: 22px 22px; animation: sweep 8s linear infinite; }
319	@keyframes sweep { to { transform: rotate(360deg); } }
320	.canon-pulse {
321	  position: absolute; inset: 0; border-radius: 10px; pointer-events: none;
322	  background: linear-gradient(100deg, transparent 30%, rgba(127, 212, 172, 0.35) 50%, transparent 70%);
323	  transform: translateX(-100%);
324	}
325	.canon-pulse.go { animation: slide 1.2s ease-in-out; }
326	@keyframes slide { to { transform: translateX(100%); } }
327	
328	.repo-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-top: 14px; }
329	.repo-tile {
330	  border: 1px solid var(--line); border-radius: 10px; padding: 10px 12px;
331	  font-family: var(--mono); font-size: 0.74rem; display: grid; gap: 3px;
332	  transition: border-color 0.35s ease, background 0.35s ease;
333	}
334	.repo-tile .r-name { font-weight: 700; color: var(--ink); }
335	.repo-tile .r-ref { color: var(--ink-soft); transition: color 0.35s ease; }
336	.repo-tile.stale .r-ref { color: var(--amber); }
337	.repo-tile.fresh { border-color: var(--accent); background: var(--accent-wash); }
338	.repo-tile.fresh .r-ref { color: var(--accent-deep); font-weight: 700; }
339	.fleet-board .viz-caption { margin-top: 12px; }
340	
341	/* --------------------------- growth loop --------------------------- */
342	.growth-viz svg { width: 100%; max-width: 520px; height: auto; display: block; margin: 0 auto; }
343	.loop-ring { fill: none; stroke: var(--line); stroke-width: 2; }
344	.loop-flow {
345	  fill: none; stroke: var(--accent); stroke-width: 2.5;
346	  stroke-dasharray: 14 22; stroke-linecap: round;
347	  animation: flow 26s linear infinite;
348	}
349	@keyframes flow { to { stroke-dashoffset: -1256; } }
350	.loop-node circle { fill: var(--paper); stroke: var(--ink); stroke-width: 2; }
351	.loop-node text { font-family: var(--mono); font-size: 13.5px; fill: var(--ink); }
352	.crystal-center { transform-origin: 280px 280px; animation: breathe 6s ease-in-out infinite; }
353	@keyframes breathe { 50% { transform: scale(1.05); } }
354	.rungs {
355	  list-style: none; margin: 1.6em 0 0; display: grid; gap: 8px;
356	  font-family: var(--mono); font-size: 0.86rem;
357	}
358	.rung {
359	  display: grid; grid-template-columns: 5.5rem 8rem 1fr; align-items: center; gap: 12px;
360	  border: 1.5px solid currentColor; border-radius: 999px; padding: 9px 18px;
361	}
362	.rung-name { font-weight: 700; }
363	.rung-cost { opacity: 0.75; }
364	.rung-force { opacity: 0.75; }
365	/* The last rung is the one that costs nothing and still binds — the whole point. */
366	.rung-final { background: #7fd4ac; border-color: #7fd4ac; color: var(--term-bg); }
367	.rung-final .rung-cost, .rung-final .rung-force { opacity: 0.9; font-weight: 620; }
368	
369	/* ---------------------- multipliers preamble ----------------------- */
370	.mult-intro { padding: clamp(56px, 8vw, 104px) 0 clamp(28px, 4vw, 44px); border-top: 1px solid var(--line); }
371	.mult-lede { font-size: clamp(1.05rem, 1.9vw, 1.3rem); color: var(--ink-soft); }
372	
373	/* ------------------------------ canon ------------------------------ */
374	.canon { padding: clamp(64px, 10vw, 130px) 0; border-top: 1px solid var(--line); background: var(--paper-2); }
375	
376	.stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; margin: 2em 0 2.6em; }
377	.stat {
378	  background: var(--paper); border: 1px solid var(--line); border-radius: var(--radius);
379	  padding: 20px 22px;
380	}
381	.stat b { display: block; font-size: clamp(1.7rem, 3vw, 2.4rem); letter-spacing: -0.03em; line-height: 1.1; color: var(--accent-deep); }
382	.stat span { font-size: 0.82rem; color: var(--ink-soft); font-family: var(--mono); }
383	
384	.spotlight { display: grid; grid-template-columns: repeat(2, 1fr); gap: 14px; }
385	.spot {
386	  border: 1.5px solid var(--ink); border-radius: var(--radius); padding: 24px;
387	  background: var(--paper); box-shadow: 0 2px 0 var(--ink);
388	}
389	.spot:first-child { grid-column: 1 / -1; background: var(--ink); color: var(--paper); }
390	.spot:first-child p { color: #c9cfbf; }
391	.spot h3 { margin-bottom: 0.4em; }
392	.spot:first-child h3 { color: #7fd4ac; font-size: 1.4rem; }
393	.spot p { font-size: 0.94rem; color: var(--ink-soft); max-width: none; }
394	
395	/* The pack field: many packs, a handful declared. No labels — the point is
396	   the count and the choosing, not which ones. */
397	.pack-field { margin: 0 0 2.4em; }
398	.pack-field svg { width: 100%; height: auto; display: block; }
399	.pf-cell {
400	  fill: none; stroke: var(--ink); stroke-width: 1.4; stroke-linejoin: round; opacity: 0.22;
401	}
402	.pf-cell.pf-on {
403	  fill: var(--accent-wash); stroke: var(--accent-deep); stroke-width: 1.8; opacity: 1;
404	  animation: pf-glow 9s ease-in-out infinite;
405	  animation-delay: calc(var(--i) * -0.7s);
406	}
407	@keyframes pf-glow { 0%, 100% { opacity: 1; } 45% { opacity: 0.45; } }
408	
409	/* ------------------------------ adopt ------------------------------ */
410	.adopt { padding: clamp(64px, 10vw, 130px) 0; border-top: 1px solid var(--line); }
411	.adopt-grid { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: clamp(32px, 5vw, 64px); align-items: start; }
412	.steps { margin: 1.5em 0 0 1.2em; display: grid; gap: 1em; color: var(--ink-soft); }
413	.steps li::marker { font-family: var(--mono); font-weight: 700; color: var(--accent-deep); }
414	.steps b { color: var(--ink); }
415	.assure { margin: 2em 0 0; list-style: none; display: grid; gap: 0.6em; font-size: 0.9rem; color: var(--ink-soft); }
416	.assure li { padding-left: 1.5em; position: relative; }
417	.assure li::before { content: "✓"; position: absolute; left: 0; color: var(--accent); font-weight: 700; }
418	
419	/* ------------------------------- faq ------------------------------- */
420	.faq { padding: clamp(64px, 10vw, 120px) 0; border-top: 1px solid var(--line); background: var(--paper-2); }
421	.faq details { border-bottom: 1px solid var(--line); }
422	.faq details:first-of-type { border-top: 1px solid var(--line); margin-top: 2em; }
423	.faq summary {
424	  cursor: pointer; padding: 18px 36px 18px 4px; font-weight: 650; font-size: 1.02rem;
425	  list-style: none; position: relative;
426	}
427	.faq summary::-webkit-details-marker { display: none; }
428	.faq summary::after {
429	  content: "+"; position: absolute; right: 8px; top: 50%; transform: translateY(-50%);
430	  font-family: var(--mono); font-size: 1.2rem; color: var(--accent-deep); transition: transform 0.2s ease;
431	}
432	.faq details[open] summary::after { transform: translateY(-50%) rotate(45deg); }
433	.faq details p { padding: 0 4px 20px; color: var(--ink-soft); max-width: 68ch; }
434	
435	/* ------------------------------ footer ----------------------------- */
436	.footer { border-top: 1px solid var(--line); padding: 48px 0 32px; }
437	.footer-grid { display: flex; justify-content: space-between; align-items: flex-start; gap: 24px; flex-wrap: wrap; }
438	.brand-footer { font-size: 1.15rem; }
439	.footer-tag { font-family: var(--mono); font-size: 0.8rem; color: var(--ink-soft); margin-top: 8px; }
440	.footer-links { display: flex; gap: 20px; flex-wrap: wrap; }
441	.footer-links a { color: var(--ink-soft); text-decoration: none; font-size: 0.9rem; }
442	.footer-links a:hover { color: var(--ink); }
443	.footer-meta {
444	  margin-top: 32px; padding-top: 20px; border-top: 1px solid var(--line);
445	  display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap;
446	  font-size: 0.8rem; color: var(--ink-soft);
447	}
448	.footer-meta p { max-width: 72ch; }
449	/* The copyright carries the released version in its title tooltip. */
450	.copyright { cursor: help; }
451	
452	/* ---------------------------- responsive --------------------------- */
453	@media (max-width: 940px) {
454	  .mech-grid, .adopt-grid { grid-template-columns: 1fr; }
455	  .mech-grid-flip > .mech-copy { order: 0; }
456	  .why-grid { grid-template-columns: 1fr; }
457	  .stats { grid-template-columns: repeat(2, 1fr); }
458	  .spotlight { grid-template-columns: 1fr; }
459	  .repo-grid { grid-template-columns: repeat(2, 1fr); }
460	  .nav nav a:not(.nav-cta) { display: none; }
461	  .rung { grid-template-columns: 1fr; gap: 2px; border-radius: var(--radius); text-align: left; }
462	}
463	
464	/* SVG text scales with the viewBox, so on a narrow screen the chart's labels
465	   shrink below reading size. Enlarge them in user units to compensate. */
466	@media (max-width: 720px) {
467	  .cx-axis-label, .cx-meter-head, .cx-caption, .cx-pin text { font-size: 18px; }
468	  .cx-meter-label { font-size: 19px; }
469	  .cx-key { font-size: 21px; }
470	  .cx-line { stroke-width: 4.5; }
471	}
472	
473	/* -------------------------- reduced motion ------------------------- */
474	@media (prefers-reduced-motion: reduce) {
475	  html { scroll-behavior: auto; }
476	  .reveal, #term-body .t-line { opacity: 1; transform: none; transition: none; }
477	  .adopt-result { opacity: 1; }
478	  .caret, .clock-hand, .loop-flow, .crystal-center, .canon-pulse, .pf-cell,
479	  .cx-freed { animation: none !important; }
480	  .cx-pin, .cx-key { opacity: 1 !important; }
481	  .btn { transition: none; }
482	}
483	
484	/* ---------- Legal pages (privacy) ---------- */
485	.legal { padding: 72px 0 40px; }
486	.legal-title { font-size: clamp(2.2rem, 5vw, 3.4rem); margin-bottom: 0.4em; }
487	.legal-lede { font-size: 1.15rem; color: var(--ink-soft); margin-bottom: 1.6em; }
488	.legal p { margin-bottom: 1.1em; }
489	.legal h2 { font-size: clamp(1.3rem, 2.4vw, 1.7rem); margin: 1.8em 0 0.5em; }
490	.legal a { color: var(--accent-deep); }
