cd /home/user/ClaudiniteWebsite
cat >> site/assets/style.css <<'CSSEOF'

/* ======================= the desk scene =======================
   The hero narrative: one operator's desk over eight beats. Everything is
   driven by cumulative beat classes (.b1 … .b8) that assets/main.js adds to
   the svg, so each visual state is a plain rule keyed off a beat rather than
   one long keyframe timeline. Motion signature is load-bearing: the agent
   eases (organic, and it decays), the robot steps (deterministic, and it
   does not). */
.scene { margin: clamp(28px, 4vw, 48px) auto 0; max-width: 1040px; }
.scene svg { width: 100%; height: auto; display: block; overflow: visible; }
.scene-caption { display: flex; align-items: center; justify-content: center; gap: 14px; flex-wrap: wrap; margin-top: 10px; }

/* The claim the whole scene stands in front of. */
.sc-curve {
  fill: none; stroke: var(--accent); stroke-width: 2.5; opacity: 0.13;
  stroke-linecap: round; stroke-dasharray: 1; stroke-dashoffset: 1;
  transition: stroke-dashoffset 2.4s linear;
}
.b1 .sc-curve { stroke-dashoffset: 0.86; }
.b2 .sc-curve { stroke-dashoffset: 0.72; }
.b3 .sc-curve { stroke-dashoffset: 0.6; }
.b4 .sc-curve { stroke-dashoffset: 0.47; }
.b5 .sc-curve { stroke-dashoffset: 0.35; }
.b6 .sc-curve { stroke-dashoffset: 0.22; }
.b7 .sc-curve { stroke-dashoffset: 0.11; }
.b8 .sc-curve { stroke-dashoffset: 0; }

.sc-ground { stroke: var(--line); stroke-width: 1.5; fill: none; }
.sc-desk { stroke: var(--ink); stroke-width: 2.5; fill: none; stroke-linecap: round; }
.sc-keys { fill: var(--paper-2); stroke: var(--ink); stroke-width: 2; }

/* --- screens: each slot is fixed, so one arriving never moves the others --- */
.sc-screen { opacity: 0; transform: scale(0.92); transform-box: fill-box; transform-origin: center;
  transition: opacity 0.35s ease-out, transform 0.35s ease-out; }
.sc-glass { fill: var(--paper); stroke: var(--ink); stroke-width: 2; }
.sc-bar { stroke: var(--line); stroke-width: 1.5; fill: none; }
.sc-stand, .sc-arm { stroke: var(--ink-soft); stroke-width: 2; fill: none; }
.sc-code {
  stroke: var(--ink-soft); stroke-width: 3; fill: none; stroke-linecap: round; opacity: 0;
  animation: sc-type 3.6s linear infinite; animation-delay: calc(var(--n) * 0.72s);
}
.sc-code-good { stroke: var(--accent); }
@keyframes sc-type { 0%, 4% { opacity: 0; } 10%, 82% { opacity: 0.55; } 92%, 100% { opacity: 0; } }
/* Faster work once the agent is grown, faster still once the robot is on it. */
.b2 .sc-code { animation-duration: 1.8s; animation-delay: calc(var(--n) * 0.36s); }
.b5 .sc-code { animation-duration: 1.4s; animation-delay: calc(var(--n) * 0.28s); }

.sc-tech { fill: none; stroke: var(--ink); stroke-width: 2; transition: stroke 0.4s ease, fill 0.4s ease; }
.sc-tech-dot { fill: var(--ink); transition: fill 0.4s ease; }
.sc-known .sc-tech { stroke: var(--accent-deep); fill: var(--accent-wash); }
.sc-known .sc-tech-dot { fill: var(--accent-deep); }

/* --- bugs: what a crusty corpus starts writing into the work --- */
.sc-bug { opacity: 0; transform: scale(0.5); transform-box: fill-box; transform-origin: center;
  transition: opacity 0.15s ease-out, transform 0.15s ease-out; }
.sc-x { stroke: var(--red); stroke-width: 3; fill: none; stroke-linecap: round; }
.sc-zig { stroke: var(--red); stroke-width: 3; fill: none; stroke-linecap: round; stroke-linejoin: round; }
.b4 .sc-bug { opacity: 1; transform: scale(1); }
.b6 .sc-bug { opacity: 0; transform: scale(1); }
.sc-tick { stroke: var(--accent); stroke-width: 3; fill: none; stroke-linecap: round;
  stroke-linejoin: round; opacity: 0; transition: opacity 0.3s ease; }
.b6 #sc-s1 .sc-tick { opacity: 1; }
.b7 #sc-s1 .sc-tick { opacity: 0; }

/* --- work lines: dashes running from whoever is serving a screen --- */
.sc-wl { fill: none; stroke-width: 1.5; stroke-linecap: round; opacity: 0; transition: opacity 0.4s ease; }
.sc-wl-a { stroke: var(--accent); stroke-dasharray: 4 10; animation: sc-flow 2s linear infinite; }
.sc-wl-r { stroke: var(--accent); stroke-dasharray: 6 6; animation: sc-flow 1.2s steps(6) infinite; }
@keyframes sc-flow { to { stroke-dashoffset: -28; } }
.b2 .sc-wl-a { animation-duration: 1s; }
/* Stuttering output while the agent is crusted over. */
.b3 .sc-wl-a { stroke-dasharray: 2 14; animation-timing-function: steps(6); }
.b6 .sc-wl-a { stroke-dasharray: 4 10; animation-timing-function: linear; }

/* --- the agents: our crystal, grown and then relieved --- */
.sc-agent { transform-box: fill-box; transform-origin: bottom center;
  transition: transform 0.6s ease; }
.sc-cryst { transition: fill 0.8s ease; }
.sc-facet { transition: opacity 0.8s ease; }
#sc-agent-a { transform: scale(1); }
.b2 #sc-agent-a { transform: scale(1.4); }
.b3 #sc-agent-a { transform: scale(1.8); }
.b6 #sc-agent-a { transform: scale(0.9); }
#sc-agent-b { opacity: 0; transform: scale(0.7); transition: opacity 0.5s ease, transform 0.6s ease; }
.b2 #sc-agent-b { opacity: 1; transform: scale(1); }
.b6 #sc-agent-b { transform: scale(0.8); }

/* Cruft accretes as bad little copies of itself, plus staleness. */
.sc-crust { opacity: 0; transition: opacity 0.5s ease; }
.b3 .sc-crust { opacity: 1; }
.b6 .sc-crust { opacity: 0; }
.sc-barn { fill: none; stroke: var(--ink-soft); stroke-width: 1.2; transform-box: fill-box;
  transform-origin: center; transform: scale(0); transition: transform 0.15s ease-out;
  transition-delay: calc(var(--n) * 0.12s); }
.b3 .sc-barn { transform: scale(1); }
.b6 .sc-barn { transform: scale(0); transition-delay: calc(var(--n) * 0.06s); }
.sc-moss { fill: var(--amber-wash); stroke: var(--amber); stroke-width: 1.2; }
.sc-moss-2 { opacity: 0; transition: opacity 0.4s ease; }
.b4 .sc-moss-2 { opacity: 1; }
.sc-drip { stroke: var(--amber); stroke-width: 1.5; fill: none; stroke-linecap: round; }
.b3 .sc-cryst { fill: var(--amber-wash); }
.b3 .sc-facet { opacity: 0.25; }
.b6 .sc-cryst { fill: var(--accent-wash); }
.b6 .sc-facet { opacity: 0.6; }

/* Jolts: never more than one per agent at a time, co-prime periods. */
.sc-jolt { fill: none; stroke: var(--amber); stroke-width: 2; stroke-linecap: round; opacity: 0; }
.b4 .sc-jolt-1 { animation: sc-spark 0.9s steps(1) infinite; }
.b4 .sc-jolt-2 { animation: sc-spark 1.3s steps(1) infinite; }
.b4 .sc-jolt-3 { animation: sc-spark 1.1s steps(1) infinite; }
.b6 .sc-jolt { animation: none !important; opacity: 0; }
@keyframes sc-spark { 0%, 12% { opacity: 1; } 13%, 100% { opacity: 0; } }

/* --- the robot: everything the crystal is not. Straight, ruled, stepped. --- */
.sc-robot {
  opacity: 0; transform: translateX(40px) scale(0.55);
  transform-box: fill-box; transform-origin: bottom center;
  transition: opacity 0.3s steps(4), transform 0.9s steps(8);
}
.b5 .sc-robot { opacity: 1; transform: translateX(0) scale(0.55); }
.b6 .sc-robot { transform: translateX(0) scale(1.3); transition: transform 0.6s steps(4); }
.b8 .sc-robot { transform: translateX(0) scale(1.6); }
.sc-bot-body, .sc-bot-head { fill: var(--paper); stroke: var(--ink); stroke-width: 2; }
.sc-bot-grid { stroke: var(--ink-soft); stroke-width: 0.8; fill: none; }
.sc-eye { fill: var(--ink); }
.sc-bot-ant, .sc-bot-feet { stroke: var(--ink); stroke-width: 2; fill: none; stroke-linecap: round; }
.sc-bot-arm { stroke: var(--ink); stroke-width: 1.5; fill: none; stroke-linecap: round;
  opacity: 0; transition: opacity 0.3s steps(2); }
.b6 .sc-bot-arm { opacity: 1; }
/* Its heartbeat is a metronome, where the crystal breathes. */
.sc-bot-dot { fill: var(--accent); }
.b5 .sc-bot-dot { animation: sc-blink 1s steps(1) infinite; }
@keyframes sc-blink { 0%, 50% { opacity: 1; } 51%, 100% { opacity: 0.15; } }

/* --- the pack arriving from off-screen, and being had by both at once --- */
.sc-pack { opacity: 0; }
.b7 .sc-pack { opacity: 1; }
.sc-pack-arc { fill: none; stroke: var(--line); stroke-width: 1.5; stroke-dasharray: 1 6; opacity: 0; }
.b7 .sc-pack-arc { animation: sc-fade-io 2.5s ease both; }
@keyframes sc-fade-io { 0% { opacity: 0; } 20%, 60% { opacity: 1; } 100% { opacity: 0; } }
.sc-pack-cell { fill: var(--accent-wash); stroke: var(--accent-deep); stroke-width: 1.8; opacity: 0; }
.b7 .sc-pack-cell { animation: sc-arrive 0.9s ease-out both; }
@keyframes sc-arrive {
  0% { opacity: 0; transform: translate(106px, -130px) scale(0.6); }
  70% { opacity: 1; transform: translate(0, 0) scale(1); }
  85% { transform: translate(0, 0) scale(1.3); }
  100% { opacity: 0; transform: translate(0, 0) scale(1); }
}
.sc-pack-shard { fill: var(--accent-wash); stroke: var(--accent-deep); stroke-width: 1.5; opacity: 0; }
.b7 .sc-shard-a { animation: sc-shard-a 0.45s ease-in 0.85s both; }
.b7 .sc-shard-b { animation: sc-shard-b 0.45s ease-in 0.85s both; }
@keyframes sc-shard-a { 0% { opacity: 1; } 100% { opacity: 0; transform: translate(-52px, 82px) scale(0.2); } }
@keyframes sc-shard-b { 0% { opacity: 1; } 100% { opacity: 0; transform: translate(58px, 46px) scale(0.2); } }
/* Absorption reuses the chart's freed-flash: knowledge lands, then output. */
.b7 .sc-cryst, .b7 .sc-bot-body { animation: cx-freed 0.6s ease-out 1.25s; }

/* --- the person: two authored poses, crossfaded. Never tweened. --- */
.sc-chair { stroke: var(--ink); stroke-width: 2.5; fill: none; stroke-linecap: round; }
.sc-body, .sc-limb { stroke: var(--ink); stroke-width: 4.5; fill: none;
  stroke-linecap: round; stroke-linejoin: round; }
.sc-far { opacity: 0.5; }
.sc-head { fill: var(--paper); stroke: var(--ink); stroke-width: 4; }
.sc-pose { transition: opacity 0.3s ease; }
.sc-pose-b { opacity: 0; }
.b6 .sc-pose-a { opacity: 0; }
.b6 .sc-pose-b { opacity: 1; }

.sc-typing { transform-box: fill-box; transform-origin: 34px 24px;
  animation: sc-hammer 0.26s ease-in-out infinite alternate; }
@keyframes sc-hammer { from { transform: rotate(-5deg); } to { transform: rotate(5deg); } }
.b4 .sc-typing { animation-duration: 0.2s; }
.sc-hit { stroke: var(--ink); stroke-width: 2; fill: none; stroke-linecap: round;
  animation: sc-blink 0.3s steps(1) infinite; }

/* The whole "frustrated face", with no face. */
.sc-vex path, .sc-vex { stroke: var(--ink); stroke-width: 2.5; fill: none; stroke-linecap: round; }
.sc-vex-1 { animation: sc-vex 0.5s steps(1) infinite; }
.sc-vex-2 { animation: sc-vex 0.5s steps(1) 0.25s infinite; }
.sc-vex-3 { opacity: 0; animation: sc-vex 0.4s steps(1) 0.12s infinite; animation-play-state: paused; }
.b4 .sc-vex-3 { animation-play-state: running; }
@keyframes sc-vex { 0%, 50% { opacity: 1; } 51%, 100% { opacity: 0.15; } }

.sc-gesture { transform-box: fill-box; transform-origin: 0 12px;
  animation: sc-point 2.4s ease-in-out infinite alternate; }
@keyframes sc-point { from { transform: rotate(0deg); } to { transform: rotate(-8deg); } }

/* --- approval chips: the contrast with fifteen seconds of typing --- */
.sc-chip { opacity: 0; }
.sc-chip rect { fill: var(--paper-2); stroke: var(--ink); stroke-width: 1.5; }
.sc-chip text { font-family: var(--mono); font-size: 11px; font-weight: 700;
  fill: var(--ink); text-anchor: middle; letter-spacing: 0.08em; }
.b8 .sc-chip-1 { animation: sc-send 1.8s ease-out infinite; }
.b8 .sc-chip-2 { animation: sc-send 1.8s ease-out 0.6s infinite; }
.b8 .sc-chip-3 { animation: sc-send 1.8s ease-out 1.2s infinite; }
@keyframes sc-send {
  0% { opacity: 0; transform: translate(0, 0) scale(0.8); }
  15% { opacity: 1; transform: translate(14px, -6px) scale(1); }
  70% { opacity: 0.9; transform: translate(150px, -22px) scale(1); }
  100% { opacity: 0; transform: translate(220px, -30px) scale(1); }
}

/* Enlarge the chip text on narrow screens, as with the chart's labels. */
@media (max-width: 720px) {
  .sc-chip text { font-size: 15px; }
}

@media (prefers-reduced-motion: reduce) {
  #scene-viz *, #scene-viz { animation: none !important; transition: none !important; }
}
CSSEOF
