64	
65	.eyebrow {
66	  font-family: var(--mono);
67	  font-size: 0.72rem;
68	  letter-spacing: 0.16em;
69	  text-transform: uppercase;
70	  color: var(--accent-deep);
71	  margin-bottom: 1.1em;
72	}
73	.eyebrow::before { content: "◆ "; font-size: 0.85em; }
74	
75	/* ------------------------------- nav ------------------------------- */
76	.nav {
77	  position: sticky; top: 0; z-index: 50;
78	  background: color-mix(in srgb, var(--paper) 88%, transparent);
79	  backdrop-filter: blur(10px);
80	  border-bottom: 1px solid var(--line);
81	}
82	.nav-inner {
83	  max-width: 1140px; margin: 0 auto; padding: 14px 24px;
84	  display: flex; align-items: center; justify-content: space-between; gap: 16px;
85	}
86	.brand {
87	  display: inline-flex; align-items: center; gap: 9px;
88	  font-family: var(--mono); font-weight: 700; font-size: 1.05rem;
89	  color: var(--ink); text-decoration: none; letter-spacing: -0.02em;
90	}
91	.brand-glyph { width: 22px; height: 22px; color: var(--accent); }
92	.nav nav { display: flex; align-items: center; gap: 22px; }
93	.nav nav a {
94	  color: var(--ink-soft); text-decoration: none; font-size: 0.92rem; font-weight: 550;
95	}
96	.nav nav a:hover { color: var(--ink); }
97	.nav-cta {
